{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Profile — {{BUSINESS_NAME}}</title>
  <meta name="description" content="About the clinician — thoughtful, private therapy for adults in {{CITY}}, {{STATE}}.">
  <style>
    :root{--bg:#08121a;--card:#0f2730;--accent:#8fd3c7;--muted:#b3c7c1;--glass:rgba(255,255,255,0.03);}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6f3f0;background:linear-gradient(180deg,var(--bg),#061018);min-height:100vh}
    header{position:sticky;top:0;backdrop-filter:blur(6px);background:linear-gradient(90deg,rgba(2,8,12,0.6),rgba(6,14,18,0.4));border-bottom:1px solid rgba(255,255,255,0.02);}
    .nav{max-width:1100px;margin:0 auto;display:flex;align-items:center;gap:18px;padding:14px}
    .brand{font-weight:600;color:var(--accent)}
    .nav a{color:#cfe9e3;text-decoration:none;padding:8px 10px;border-radius:6px;font-size:14px}
    .nav a.active{background:rgba(143,211,199,0.08);color:var(--accent)}
    main{max-width:1100px;margin:36px auto;padding:24px;display:grid;grid-template-columns:1fr 360px;gap:28px}
    .hero{background:linear-gradient(160deg,rgba(143,211,199,0.04),transparent);border-radius:12px;padding:28px;color:#eaf6f3;box-shadow:0 6px 24px rgba(2,6,8,0.4);border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0 0 8px;font-size:26px}
    p.lead{margin:0 0 16px;color:var(--muted)}
    .cta{display:inline-block;background:var(--accent);color:#03343a;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:600}
    .aside{align-self:start;background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.02)}
    .mood-card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:14px;border-radius:10px}
    label{display:block;font-size:13px;color:var(--muted);margin-bottom:8px}
    select{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#dff7f3}
    .method{margin-top:12px;padding:12px;border-radius:8px;background:var(--glass);font-size:14px;color:var(--muted)}
    .accordion{margin-top:18px}
    .acc-item{background:transparent;border-top:1px solid rgba(255,255,255,0.02)}
    .acc-title{display:flex;justify-content:space-between;align-items:center;padding:12px;cursor:pointer;color:#cfe9e3}
    .acc-content{padding:0 12px 12px;color:var(--muted);display:none}
    .acc-content.open{display:block}
    footer{max-width:1100px;margin:28px auto;color:var(--muted);font-size:13px}
    .pattern{position:fixed;inset:0;pointer-events:none;opacity:0.08;background-image:url('assets/img/pattern.svg');background-repeat:repeat;}
    @media(max-width:880px){main{grid-template-columns:1fr;padding:16px} .nav{overflow:auto}}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <header>
    <nav class="nav" aria-label="Primary">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <a href="index.html">Practice</a>
      <a href="about.html" class="active">Profile</a>
      <a href="specialties.html">Offerings</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Investment</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Begin</a>
      <a href="contact.html">Reach Out</a>
    </nav>
  </header>

  <main>
    <section class="hero" aria-labelledby="about-heading">
      <h1 id="about-heading">Who I am and the frame I bring</h1>
      <p class="lead">I’m a licensed clinician offering focused, private therapy for adults. I draw on several evidence-informed practices and a straightforward, humane stance to help you notice patterns and try different moves in life’s complicated moments.</p>

      <div>
        <strong style="display:block;margin-bottom:8px">Private formats</strong>
        <p style="margin:0 0 12px;color:var(--muted)">Short, intensive sessions or a regular weekly rhythm — we choose what fits your goals and capacity. Everything is confidential within clinical and legal boundaries.</p>
        <a id="primary-cta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>

      <hr style="border:none;border-top:1px solid rgba(255,255,255,0.03);margin:18px 0">

      <h3 style="margin:0 0 8px">A brief clinical note</h3>
      <p style="margin:0;color:var(--muted)">My work is grounded in curiosity, respect, and specific strategies—aimed at strengthening your decision-making, relationships, and emotion-management without quick fixes or promises. We clarify goals together and agree on how to measure progress that matters to you.</p>
    </section>

    <aside class="aside">
      <div class="mood-card">
        <label for="mood">Choose your current state</label>
        <select id="mood" aria-describedby="mood-desc">
          <option value="overwhelmed">Overwhelmed — too much to hold</option>
          <option value="stuck">Stuck — noticing the same loop</option>
          <option value="numb">Numb — disconnected or flat</option>
          <option value="transition">Transitioning — big life change</option>
          <option value="clarify">Seeking clarity — want decision support</option>
        </select>
        <div id="mood-desc" class="method" aria-live="polite">Select a state to see a recommended session shape and a suggested next step.</div>
        <a id="mood-cta" class="cta" style="margin-top:10px;display:inline-block">Get matched session</a>
      </div>

      <div class="accordion" id="policyAccordion">
        <div class="acc-item">
          <button class="acc-title" aria-expanded="false">Session boundaries<span aria-hidden="true">▾</span></button>
          <div class="acc-content">Sessions typically last 45–60 minutes. We’ll set the schedule together and discuss attendance and cancellation policies up front. In time-limited intensives we clarify pacing and focus at the start.</div>
        </div>

        <div class="acc-item">
          <button class="acc-title" aria-expanded="false">Confidentiality & limits<span aria-hidden="true">▾</span></button>
          <div class="acc-content">Notes and communications are kept private within legal and ethical limits (e.g., imminent risk to self or others, court orders). I will always try to be transparent about confidentiality and the information I record.</div>
        </div>

        <div class="acc-item">
          <button class="acc-title" aria-expanded="false">Technology, records & contact<span aria-hidden="true">▾</span></button>
          <div class="acc-content">Telehealth and secure messaging are available. I maintain minimal clinical records that summarize sessions and care planning. For non-urgent questions, email {{EMAIL}}; for scheduling call {{PHONE}}.</div>
        </div>
      </div>

      <p style="margin-top:12px;font-size:13px;color:var(--muted)">If you are in immediate danger or are experiencing a life-threatening emergency, call your local emergency number or a crisis line (e.g., dial 988 in the U.S.). I am not an emergency service.</p>
    </aside>
  </main>

  <footer>
    <div>Licensed clinician serving {{CITY}}, {{STATE}}. Appointments by private pay or selected insurers. No guarantees are made about outcomes.</div>
  </footer>

  <script>
    (function(){
      const moodSelect = document.getElementById('mood');
      const moodDesc = document.getElementById('mood-desc');
      const moodCta = document.getElementById('mood-cta');

      const map = {
        overwhelmed:{text:'Short, focused sessions to stabilize and make practical shifts — we prioritize what reduces immediate load.',cta:'Book a stabilizing session'},
        stuck:{text:'A small series of sessions to identify recurring patterns and try specific experiments between meetings.',cta:'Start a focused series'},
        numb:{text:'Gentle pacing with attention to bodily sensing and reconnection; pacing is collaborative and slow is fine.',cta:'Request gentle pacing'},
        transition:{text:'An intensive check-in to set priorities and practical next steps for a life change; we can design one or two extended sessions.',cta:'Discuss a transition plan'},
        clarify:{text:'Decision-focused sessions with structured tools for weighing options and clarifying values.',cta:'Begin decision support'}
      };

      function update(){
        const val = moodSelect.value;
        moodDesc.textContent = map[val].text;
        moodCta.textContent = map[val].cta;
        moodCta.href = '{{PRIMARY_CTA_URL}}';
      }

      moodSelect.addEventListener('change',update);
      update();

      // Accordion behavior
      document.querySelectorAll('.acc-title').forEach(btn=>{
        btn.addEventListener('click',()=>{
          const expanded = btn.getAttribute('aria-expanded') === 'true';
          btn.setAttribute('aria-expanded', String(!expanded));
          const content = btn.nextElementSibling;
          content.classList.toggle('open');
        });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Services and specialties. Short intensives and regular sessions for adults in {{CITY}}, {{STATE}}.">
  <style>
    :root{--bg:#061018;--panel:#112a2e;--accent:#b8ffd6;--muted:#9fcbbf}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;background:radial-gradient(circle at 10% 20%,#08323a 0%,#061018 40%);color:#dff7f3;min-height:100vh}
    header{padding:14px 24px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .nav{max-width:1100px;margin:0 auto;display:flex;align-items:center;gap:18px}
    .nav a{color:#cfeee7;text-decoration:none;padding:8px;border-radius:6px}
    .nav a.active{background:rgba(184,255,214,0.07);color:var(--accent)}
    .wrap{max-width:1100px;margin:28px auto;padding:16px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:22px}
    .panel{background:var(--panel);border-radius:12px;padding:18px;border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0 0 8px}
    .offer{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:14px;border-radius:10px;margin-bottom:12px}
    ul{margin:8px 0 0;padding-left:18px;color:var(--muted)}
    .package{display:flex;justify-content:space-between;align-items:center;margin-top:12px}
    .cta{background:var(--accent);color:#042b28;padding:10px 12px;border-radius:8px;text-decoration:none;font-weight:700}
    .mood{margin-top:10px}
    .small{font-size:13px;color:#9fcbbf}
    @media(max-width:880px){.grid{grid-template-columns:1fr}}
    .pattern{position:fixed;inset:0;pointer-events:none;opacity:0.06;background-image:url('assets/img/pattern.svg');background-repeat:repeat}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <header>
    <nav class="nav" aria-label="Primary">
      <div style="font-weight:700;color:var(--accent)">{{BUSINESS_NAME}}</div>
      <a href="index.html">Practice</a>
      <a href="about.html">Profile</a>
      <a href="specialties.html" class="active">Offerings</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Investment</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Begin</a>
      <a href="contact.html">Reach Out</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="grid">
      <section class="panel">
        <h1>What I work with</h1>
        <p class="small">Common themes people bring: relationship transitions, burnout and overwhelm, decision crossroads, grief and identity shifts, and patterns that keep repeating.</p>

        <div class="offer">
          <strong>Focused Intensives</strong>
          <p class="small">1–3 extended sessions designed to map the issue and try immediate, practical shifts. Good when you need momentum in a limited time.</p>
        </div>

        <div class="offer">
          <strong>Short Series</strong>
          <p class="small">4–8 weekly meetings with clear goals and small between-session experiments. Intended for problem-focused work with measurable steps.</p>
        </div>

        <div class="offer">
          <strong>Maintenance & Care</strong>
          <p class="small">Less frequent, ongoing sessions for people who want professional reflection and steady support without weekly scheduling pressure.</p>
        </div>

        <h3 style="margin-top:14px">Techniques I blend</h3>
        <ul>
          <li>Practical cognitive strategies for clearer choices</li>
          <li>Behavioral experiments and gentle exposure to reduce avoidance</li>
          <li>Emotion-focused noticing and somatic grounding</li>
          <li>Interpersonal pattern work focused on communication and boundaries</li>
        </ul>

        <div class="package">
          <div>
            <div style="font-weight:700">Tailored plan</div>
            <div class="small">We design a plan together—no one-size-fits-all pricing language here.</div>
          </div>
          <a id="offer-cta" class="cta" href="{{PRIMARY_CTA_URL}}">Talk about fit</a>
        </div>
      </section>

      <aside class="panel">
        <div>
          <label for="mood2" style="display:block;color:var(--muted);margin-bottom:8px">How are you feeling right now?</label>
          <select id="mood2" aria-describedby="mood2-desc" style="width:100%;padding:10px;border-radius:8px;background:#081b1c;color:#dff7f3;border:1px solid rgba(255,255,255,0.03)">
            <option value="anxious">Anxious — tight, racing</option>
            <option value="confused">Confused — unsure where to turn</option>
            <option value="resentful">Resentful — stuck in a relationship loop</option>
            <option value="exhausted">Exhausted — low energy, worn down</option>
            <option value="planning">Planning — need help shaping choices</option>
          </select>

          <div id="mood2-desc" style="margin-top:12px;color:var(--muted);font-size:14px">Pick a state to see a recommended offering and next step.</div>
          <a id="mood2-cta" class="cta" style="display:inline-block;margin-top:12px">Find a good starting point</a>
        </div>

        <hr style="border:none;border-top:1px solid rgba(255,255,255,0.02);margin:16px 0">

        <div style="font-size:13px;color:var(--muted)">
          <strong>Confidentiality & limits</strong>
          <p style="margin:8px 0 0">Conversations are confidential with exceptions required by law (e.g., imminent harm). We will review these boundaries before work begins.</p>
        </div>

        <p style="margin-top:12px;font-size:13px;color:var(--muted)">If you are in immediate danger, call local emergency services or a crisis line (for U.S. dial 988). I am not an emergency responder.</p>
      </aside>
    </div>
  </main>

  <script>
    (function(){
      const sel = document.getElementById('mood2');
      const desc = document.getElementById('mood2-desc');
      const cta = document.getElementById('mood2-cta');
      const map = {
        anxious:{text:'Short intensives with grounding and pacing can help reduce acute distress and create breathing room.',cta:'Book a grounding intensive'},
        confused:{text:'A short series to map options and try concrete decision tools tends to be helpful here.',cta:'Begin option-mapping'},
        resentful:{text:'Interpersonal-focused work and practical boundary testing in real life can shift persistent cycles.',cta:'Explore relational work'},
        exhausted:{text:'Maintenance or very short, practical sessions to reduce load and recover energy are often useful.',cta:'Arrange an energy-focused check-in'},
        planning:{text:'Decision-clarifying sessions with values-focused exercises support practical next steps and timelines.',cta:'Schedule decision support'}
      };
      function update(){
        const v = sel.value;
        desc.textContent = map[v].text;
        cta.textContent = map[v].cta;
        cta.href = '{{PRIMARY_CTA_URL}}';
      }
      sel.addEventListener('change',update);
      update();
    })();
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Method — {{BUSINESS_NAME}}</title>
  <meta name="description" content="How therapy sessions are structured and what to expect — clear agreements, simple experiments, and steady reflection.">
  <style>
    :root{--bg:#071519;--card:#0f2a2b;--accent:#a1ffe6;--muted:#9bd5c9}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto;color:#eafefb;background:linear-gradient(180deg,#08141a 0%,#041014 100%);min-height:100vh}
    header{padding:12px 20px}
    .nav{max-width:1100px;margin:0 auto;display:flex;align-items:center;gap:16px}
    .nav a{color:#cdeee7;text-decoration:none;padding:8px;border-radius:6px}
    .nav a.active{background:rgba(161,255,230,0.06);color:var(--accent)}
    main{max-width:1100px;margin:28px auto;padding:18px;display:grid;grid-template-columns:1fr 360px;gap:22px}
    .card{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.02)}
    h1{margin:0 0 8px}
    .pillars{display:flex;gap:12px;flex-wrap:wrap;margin-top:12px}
    .pillar{flex:1 1 160px;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent)}
    .case{margin-top:14px;background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
    .cta{background:var(--accent);color:#022524;padding:10px 12px;border-radius:8px;text-decoration:none;font-weight:700}
    .mood-sbox{margin-top:10px}
    .pattern{position:fixed;inset:0;pointer-events:none;opacity:0.07;background-image:url('assets/img/pattern.svg');background-repeat:repeat}
    @media(max-width:880px){main{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <header>
    <nav class="nav" aria-label="Primary">
      <div style="font-weight:700;color:var(--accent)">{{BUSINESS_NAME}}</div>
      <a href="index.html">Practice</a>
      <a href="about.html">Profile</a>
      <a href="specialties.html">Offerings</a>
      <a href="approach.html" class="active">Method</a>
      <a href="fees.html">Investment</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Begin</a>
      <a href="contact.html">Reach Out</a>
    </nav>
  </header>

  <main>
    <section class="card">
      <h1>How I work</h1>
      <p style="color:var(--muted);margin-top:6px">My approach blends clear structure with empathic presence. Sessions are practical, reflective, and tailored to what you need right now.</p>

      <div class="pillars">
        <div class="pillar">
          <strong>Clarify</strong>
          <div class="small" style="color:var(--muted);margin-top:6px;font-size:13px">Define specific aims so we measure change that matters to you.</div>
        </div>
        <div class="pillar">
          <strong>Test</strong>
          <div class="small" style="color:var(--muted);margin-top:6px;font-size:13px">Try small experiments between sessions — practical, low-risk adjustments.</div>
        </div>
        <div class="pillar">
          <strong>Reflect</strong>
          <div class="small" style="color:var(--muted);margin-top:6px;font-size:13px">Notice what shifts and why, then refine the plan together.</div>
        </div>
      </div>

      <div class="case">
        <strong>Case note (anonymized)</strong>
        <p style="margin:8px 0 0;color:var(--muted);font-size:14px">A client arrived feeling stuck at work. We clarified the specific decision, arranged two brief experiments to test energy and reactions, and used one-session summaries to guide the next meeting. The focus stayed on manageable moves rather than wholesale life redesign.</p>
      </div>

      <div style="margin-top:12px;display:flex;gap:10px;align-items:center">
        <a id="method-cta" class="cta" href="{{PRIMARY_CTA_URL}}">Plan a first meeting</a>
        <div style="color:var(--muted);font-size:13px">Typical session length 45–60 min; intensives available on request.</div>
      </div>
    </section>

    <aside class="card">
      <div>
        <label for="mood3" style="display:block;color:var(--muted);margin-bottom:8px">Select your current phrase</label>
        <select id="mood3" style="width:100%;padding:10px;border-radius:8px;background:#081b1c;color:#dff7f3;border:1px solid rgba(255,255,255,0.03)">
          <option value="racing">Racing thoughts</option>
          <option value="tentative">Tentative — want to try something small</option>
          <option value="lonely">Lonely — seeking connection</option>
          <option value="stagnant">Stagnant — not moving forward</option>
          <option value="urgent">Urgent — need immediate clarity</option>
        </select>

        <div id="mood3-desc" style="margin-top:12px;color:var(--muted)">Choose to see a recommended session shape and a tailored CTA.</div>
        <a id="mood3-cta" class="cta" style="display:inline-block;margin-top:12px">Choose a starting step</a>

        <hr style="border:none;border-top:1px solid rgba(255,255,255,0.02);margin:16px 0">

        <details style="color:var(--muted);font-size:14px">
          <summary style="cursor:pointer;font-weight:600">Confidentiality and scope</summary>
          <div style="margin-top:8px">Information shared in sessions is confidential, with exceptions for safety and legal requirements. We will review limits and record-keeping practices before beginning work together.</div>
        </details>

        <p style="margin-top:12px;font-size:13px;color:var(--muted)">If you are in immediate danger, call your local emergency services or a crisis line (e.g., 988 in the U.S.). This service does not replace emergency responders.</p>
      </div>
    </aside>
  </main>

  <script>
    (function(){
      const sel = document.getElementById('mood3');
      const desc = document.getElementById('mood3-desc');
      const cta = document.getElementById('mood3-cta');
      const map = {
        racing:{text:'A short, paced session with grounding tools and a single decision task helps reduce cognitive noise.',cta:'Book a noise-reduction visit'},
        tentative:{text:'One low-stakes experiment and a reflective check-in; we keep the steps small and trackable.',cta:'Try a micro-experiment'},
        lonely:{text:'We focus on relationship patterns and safe ways to practice connection; sessions include communication scripts to try between meetings.',cta:'Begin relational work'},
        stagnant:{text:'A short series that targets one bottleneck with practical steps and accountability.',cta:'Start a targeted series'},
        urgent:{text:'An extended intake or an intensive session can help create immediate clarity and next steps.',cta:'Request an intensive'}
      };
      function update(){
        const v = sel.value;
        desc.textContent = map[v].text;
        cta.textContent = map[v].cta;
        cta.href = '{{PRIMARY_CTA_URL}}';
      }
      sel.addEventListener('change',update);
      update();
    })();
  </script>
</body>
</html>"} 
